files.after:
.ui_themePreview {
  display: block;

  .ant-tree .ant-tree-node-content-wrapper {
    color: var(--ui-theme-preview-color, #334155);
    padding: var(--ui-theme-preview-spacing, 8px 12px);
    border-radius: var(--ui-theme-preview-radius, 6px);
  }

  .ant-tree .ant-tree-node-content-wrapper:hover {
    background: var(--ui-theme-preview-color, #334155);
    padding: var(--ui-theme-preview-spacing, 8px 12px);
    border-radius: var(--ui-theme-preview-radius, 6px);
  }
}
